import { createHmac } from "node:crypto";
import { describe, expect, it } from "vitest";
import { verifyToken } from "../src/auth/jwt";

const SECRET = "test-secret";
const now = () => Math.floor(Date.now() / 1000);

function sign(payload: object, header: object = { alg: "HS256", typ: "JWT" }, secret = SECRET) {
  const h = Buffer.from(JSON.stringify(header)).toString("base64url");
  const p = Buffer.from(JSON.stringify(payload)).toString("base64url");
  const s = createHmac("sha256", secret).update(`${h}.${p}`).digest("base64url");
  return `${h}.${p}.${s}`;
}

describe("verifyToken", () => {
  it("accepts a valid unexpired token and returns its claims", () => {
    const exp = now() + 60;
    expect(verifyToken(sign({ sub: "user-1", exp }), SECRET)).toEqual({ sub: "user-1", exp });
  });

  it("rejects tokens signed with a different secret", () => {
    expect(() => verifyToken(sign({ sub: "u", exp: now() + 60 }, undefined, "other"), SECRET)).toThrow();
  });

  it("rejects tampered payloads", () => {
    const [h, , s] = sign({ sub: "u", exp: now() + 60 }).split(".");
    const forged = Buffer.from(JSON.stringify({ sub: "admin", exp: now() + 60 })).toString("base64url");
    expect(() => verifyToken(`${h}.${forged}.${s}`, SECRET)).toThrow();
  });

  it("rejects expired tokens", () => {
    expect(() => verifyToken(sign({ sub: "u", exp: now() - 1 }), SECRET)).toThrow(/expired/);
  });

  it("rejects unsigned alg:none tokens", () => {
    const h = Buffer.from(JSON.stringify({ alg: "none" })).toString("base64url");
    const p = Buffer.from(JSON.stringify({ sub: "admin", exp: now() + 60 })).toString("base64url");
    expect(() => verifyToken(`${h}.${p}.`, SECRET)).toThrow();
  });

  it("rejects tokens missing required claims", () => {
    expect(() => verifyToken(sign({ sub: "u" }), SECRET)).toThrow();
  });
});

